inline bool isCombiningMark(uint32_t codepoint) { return codepoint >= 0x0300 && codepoint <= 0x036F; }

// Precomposed letter for base + combining mark, or 0.
inline uint32_t compose(uint32_t base, uint32_t mark) {
  for (const Composition &entry : kCompositions) {
    if (entry.base == base && entry.mark == mark) {
      return entry.composed;
    }
  }
  return 0;
}

